import {uid,now,createCase,event,latest,agreed,approved,reviseBriefing,freezeDocument,sign,approve,prompt,markdown,validateImport,openingFor,adoptLegacyOpenings,saveOpening,currentRound,pendingTurn,roundComplete,startRound,saveDebateReply,refreshDebatePrompt,orderedMembers,shuffleOrder,setPersona,implementerRequest,injectImplementer,skipReviewer,activeSummary,prepareSummary,useSummary,disableSummary,currentFinalSummary,prepareFinalSummary,saveFinalSummary,exportFinalSummary,implementerNote,saveImplementerNote,implementerHandoff,implementerNoteRequest,saveSimpleSignoff,skipApproval,signoffComplete,approvalSkipLabel,removeCouncilMember,restoreCouncilMember} from './model.js';
const KEY='council-of-ai.v1';const root=document.querySelector('#app');let state,tab='Briefing',handoffId=null,reviewTurnId=null,drafts={},saveError=false;
try{const raw=localStorage.getItem(KEY);state=raw?validateImport(JSON.parse(raw)):{schema:1,cases:[createCase('Your first council case')]};}catch(e){state={schema:1,cases:[createCase('Recovery workspace')]};saveError=true;setTimeout(()=>notify('Saved data could not be loaded. Export a backup before replacing storage. '+e.message,true),100);}
state.cases.forEach(adoptLegacyOpenings);
let active=state.cases[0].id;
const c=()=>state.cases.find(x=>x.id===active);
const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,v=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[v]));
const options=(items,value)=>items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('');
const date=x=>new Date(x).toLocaleString();
function notify(text,error=false){const n=$('notice');n.textContent=text;n.className=error?'error':'';n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',6500);}
function save(){try{if(saveError)throw Error('Storage is in recovery mode. Export your work before reloading.');localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'.drafts',JSON.stringify(drafts));return true;}catch(e){notify('Not saved: '+e.message+' Export a JSON backup now.',true);saveError=true;return false;}}
function action(fn){try{capture();fn();save();render();}catch(e){notify(e.message,true);}}
function capture(){root.querySelectorAll('[data-draft]').forEach(el=>drafts[`${active}:${el.id}`]=el.value);}
function restore(){root.querySelectorAll('[data-draft]').forEach(el=>{const v=drafts[`${active}:${el.id}`];if(v!==undefined)el.value=v;});}
function draftClear(...ids){for(const id of ids)delete drafts[`${active}:${id}`];}
const input=(id,value='',placeholder='')=>`<input id="${id}" data-draft value="${esc(value)}" placeholder="${esc(placeholder)}">`;
const area=(id,value='',placeholder='',wide=false)=>`<textarea id="${id}" data-draft class="${wide?'wide':''}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`;
function render(){try{localStorage.setItem(KEY+'.view',JSON.stringify({active,tab,reviewTurnId}));}catch{}const x=c(),d=latest(x);root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">Council <span>of AI</span></div><p class="tiny">Independent minds. Your direction.</p><div class="divider"></div><div class="eyebrow">Your cases</div><div class="cases">${state.cases.map(y=>`<button class="case-button ${y.id===active?'active':''}" data-case="${y.id}">${esc(y.title)}</button>`).join('')}</div><button id="newCase" class="quiet">+ Open a case</button><div class="divider"></div><div class="members"><div class="eyebrow">At the table · next round order</div>${orderedMembers(x).map((m,i)=>`<div class="member"><span class="avatar">${i+1}</span><div>${esc(m.name)}<div class="tiny">Council member</div></div><button class="remove-member" data-remove-member="${m.id}" aria-label="Remove ${esc(m.name)}" ${x.members.length<2?'disabled':''}>×</button></div>`).join('')}<div class="member"><span class="avatar">Y</span><div>You<div class="tiny">Chair · final authority</div></div></div></div><div class="divider"></div><p class="tiny">Local workspace · no AI calls<br>Your browser chats stay independent.</p></aside><main class="main"><div class="topbar"><span class="eyebrow">The chamber / ${esc(x.phase)}</span><div class="row"><button id="shuffleOrder" class="quiet" ${x.members.length<2?'disabled':''}>Shuffle speaking order</button><span class="save">${saveError?'⚠ Not saved':'Saved locally'}</span><button id="backup" class="quiet">Export backup</button><button id="import" class="quiet">Import</button><input type="file" id="file" accept=".json,application/json" class="hidden"></div></div><div class="row"><h1>${esc(x.title)}</h1>${x.paused?'<span class="pill">Paused</span>':''}${approved(x)?'<span class="pill">Chair approved'+esc(approvalSkipLabel(x))+'</span>':agreed(x)?'<span class="pill">Council agreed</span>':''}</div><p class="muted">Bring a proposal. Hear the objections. Own the decision.</p><nav class="tabs" aria-label="Case sections">${['Briefing','Openings','Debate','Summarise','Final document','Record'].map(t=>`<button data-tab="${t}" class="${t===tab?'active':''}">${t}</button>`).join('')}</nav><div class="layout"><section>${tab==='Briefing'?briefing(x):tab==='Openings'?openings(x):tab==='Debate'?debate(x):tab==='Summarise'?summaryPage(x):tab==='Final document'?final(x):record(x)}</section><aside class="panel chair"><div class="eyebrow">The chair</div><h2>Your voice, any time.</h2><p class="tiny">Interventions enter the record now and travel with the next relevant handoff. They are not sent automatically.</p><label for="interventionType">Intervention</label><select id="interventionType" data-draft>${['Add context','Challenge a claim','Redirect discussion','Request grounding'].map(t=>`<option>${t}</option>`).join('')}</select><label for="target">Addressed to</label><select id="target" data-draft><option value="all">Whole council</option>${options(x.members)}</select><label for="comment">Your comment</label>${area('comment','','A fact, a question, a change of direction…')}<div class="toolbar"><button id="interject" class="primary">Add to the record</button></div>${implementerPanel(x)}<div class="divider"></div><div class="row"><button id="pause">${x.paused?'Resume':'Pause'}</button><button id="close" class="quiet">${x.phase==='Closed'?'Reopen':'Close case'}</button></div><p class="tiny chair-foot">${x.responses.length} responses · ${x.interventions.length} interventions<br>${x.briefings.length?'Briefing v'+x.briefings.at(-1).version:'Briefing not frozen'}${d?' · Document v'+d.version:''}</p></aside></div></main></div>`;restore();if($('promptText')){const h=x.handoffs.find(h=>h.id===handoffId&&h.kind!=='Debate')||x.handoffs.filter(h=>h.kind!=='Debate').at(-1);if(h?.copiedAt){$('promptText').value=h.text;$('promptText').readOnly=true;}}bind();}
function implementerPanel(x){return `<div class="divider"></div><details id="implementerPanel" ${x.implementerPanelOpen?'open':''}><summary><strong>Implementer intervention</strong></summary><p class="tiny">Request a reality check, paste the reply, and inject it into the council. Follow-up exchanges stay in the record. Nothing is sent automatically.</p><label for="implementerRequester">Requested by</label><select id="implementerRequester" data-draft><option>Chair</option>${x.members.map(m=>`<option>${esc(m.name)}</option>`).join('')}</select><label for="implementerQuestion">Question or follow-up for the implementer</label>${area('implementerQuestion','','Paste the member’s question or write your own.')}<button id="copyImplementerRequest" ${!x.briefings.length?'disabled':''}>Copy request for implementer</button><details><summary>Request preview / manual copy</summary><textarea id="implementerRequestPreview" readonly></textarea></details><label for="implementerReply">Implementer’s reply</label>${area('implementerReply','','Paste their actual reply here.')}<label for="implementerTarget">Inject for</label><select id="implementerTarget" data-draft><option value="all">Whole council</option>${options(x.members)}</select><div class="toolbar"><button id="injectImplementer" class="primary" ${!x.briefings.length?'disabled':''}>Inject implementer reply</button></div><p class="tiny">The pending prompt updates immediately. Copy it again if already handed off. The current turn and reply draft are kept, including while paused.</p>${x.interventions.filter(i=>i.source==='Implementer').slice(-3).map(i=>`<details><summary>Implementer · ${esc(date(i.at))}</summary><p class="tiny">Requested by ${esc(i.requestedBy)}${i.roundId?' · during a round':''}</p><pre class="text">Question: ${esc(i.question||'Project update')}\n\n${esc(i.text)}</pre></details>`).join('')}</details>`;}
function personaField(x,m){return `<div class="persona-field"><label for="persona-${esc(m.id)}">${esc(m.name)}’s persona (optional)</label><input id="persona-${esc(m.id)}" data-persona="${esc(m.id)}" value="${esc(x.personas?.[m.id]||'')}" placeholder="e.g. Pragmatic architect; focus on simplicity"></div>`;}
function memberRemovalControls(x){const removed=[...new Map((x.removedMembers||[]).filter(v=>!x.members.some(m=>m.id===v.member.id)).map(v=>[v.member.id,v.member])).values()];return `<div class="toolbar">${x.members.map(m=>`<button data-remove-member="${m.id}" ${x.members.length<2?'disabled':''}>Remove ${esc(m.name)}</button>`).join('')}</div><p class="tiny">You can remove a member after the case starts. Their earlier replies and drafts stay in the record; unfinished turns are skipped. Keep at least one member.</p>${removed.length?`<details><summary>Removed members</summary><div class="toolbar">${removed.map(m=>`<button data-restore-member="${m.id}">Restore ${esc(m.name)}</button>`).join('')}</div></details>`:''}`;}
function briefing(x){return `<div class="panel"><div class="eyebrow">01 / Bring a case</div><h2>What should the council examine?</h2><label for="title">Case name</label>${input('title',x.title)}<label for="briefing">Shared briefing</label>${area('briefing',x.briefings.at(-1)?.body||'','Problem and desired outcome\n\nProject facts and constraints\n\nProposed solution\n\nAlternatives considered\n\nUncertainties and questions',true)}<p class="tiny">Freeze a version before collecting opinions. Revising creates a new version; earlier signatures and approvals become historical.</p><div class="toolbar"><button id="freezeBrief" class="primary">${x.briefings.length?'Freeze revised briefing':'Freeze briefing & open the floor'}</button></div></div><div class="panel"><h3>Introduce each council member</h3><p class="tiny">Your frozen briefing gets a short introduction automatically: who this member is, how the debate works, your authority as chair, and the final document and reservations. Copy it into a fresh chat for each member.</p><div class="toolbar" role="group" aria-label="Copy member introductions">${x.members.map(m=>`<div class="persona-copy"><button data-initiation="${esc(m.id)}" class="primary" ${!x.briefings.length||x.paused||x.phase==='Closed'?'disabled':''}>Copy for ${esc(m.name)}</button>${personaField(x,m)}</div>`).join('')}</div><p id="initiationRecipient" class="tiny"></p><label for="initiationText">Initiation text + frozen briefing</label><textarea id="initiationText" class="wide" readonly></textarea><p class="tiny">Uses the latest frozen briefing. Freeze edits above before copying. The introduction is also included in every new opening handoff.</p></div><div class="panel"><h3>The speaking order</h3><p class="tiny">One name per line. The implementer remains a separate technical witness. Changing the roster requires fresh document signatures.</p><label for="members">Council members</label>${area('members',x.members.map(m=>m.name).join('\n'))}<div class="toolbar"><button id="saveMembers">Update council</button></div>${memberRemovalControls(x)}</div>`;}
function advancedFloor(x){const handoffs=x.handoffs.filter(h=>h.kind!=='Debate');const h=handoffs.find(h=>h.id===handoffId)||handoffs.at(-1);return `<div class="panel"><div class="eyebrow">02 / Give the floor</div><h2>One useful contribution at a time.</h2><p class="tiny">Begin with independent openings. Then use a focused rebuttal circuit and an implementer check. Choose the speaker yourself.</p><div class="two"><div><label for="speaker">Speaker</label><select id="speaker" data-draft>${options(x.members)}</select></div><div><label for="kind">Handoff type</label><select id="kind" data-draft><option>Rebuttal</option><option>Grounding</option><option>Signature</option></select></div></div><label for="context">Selected debate context or grounding questions</label>${area('context','','Paste relevant replies, claim IDs, or questions. Openings deliberately omit this field.')}<div class="toolbar"><button id="prepare" class="primary" ${!x.briefings.length||x.paused||x.phase==='Closed'?'disabled':''}>Prepare handoff</button></div>${!x.briefings.length?'<p class="warning tiny">Freeze a briefing to begin.</p>':''}</div>${h?`<div class="panel"><h3>Review before passing the floor</h3><p class="tiny">${esc(h.kind)} · ${esc(h.memberId==='witness'?'Implementer':x.members.find(m=>m.id===h.memberId)?.name||'Former member')} · ${h.copiedAt?'Copied '+esc(date(h.copiedAt)):'Prepared, not copied'}</p><label for="handoffSelect">Handoff record</label><select id="handoffSelect">${handoffs.map((v,i)=>`<option value="${v.id}" ${v.id===h.id?'selected':''}>${i+1}. ${esc(v.kind)} · ${esc(v.memberId==='witness'?'Implementer':x.members.find(m=>m.id===v.memberId)?.name||'Former member')}</option>`).join('')}</select><label for="promptText">Complete prompt · editable until copied</label>${area('promptText',h.text,'',true)}<p class="tiny">Only the context shown above is included. Copying records a handoff, not confirmed delivery. Previously copied prompts stay immutable.</p><div class="toolbar"><button id="copy" class="primary" ${x.paused||x.phase==='Closed'?'disabled':''}>Copy prompt</button></div><label for="reply-${h.id}">Paste this chat’s response</label>${area('reply-'+h.id,'','Paste the complete response. Keep its original wording.')}<div class="toolbar"><button id="response">Record response</button></div><p class="tiny">Signature responses must also be reviewed and recorded in Final document.</p></div>`:''}<div class="panel"><h3>Claim ledger</h3><p class="tiny">Your discussion labels, not automatic truth assessments. Include source response IDs or evidence in the claim text.</p><label for="claim">Claim or objection</label>${area('claim','','Claim, author/source, evidence, and objection')}<label for="claimStatus">Status</label><select id="claimStatus" data-draft>${['Open','Supported','Disputed','Resolved','Deferred'].map(t=>`<option>${t}</option>`).join('')}</select><div class="toolbar"><button id="addClaim">Add claim</button></div>${x.claims.map(q=>`<div class="entry"><span class="pill">${esc(q.status)}</span><pre>${esc(q.text)}</pre><label for="claim-${q.id}">Update status</label><select id="claim-${q.id}" data-claim="${q.id}">${['Open','Supported','Disputed','Resolved','Deferred'].map(t=>`<option ${q.status===t?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}</div>`;}

function openings(x){
 const b=x.briefings.at(-1),saved=x.members.filter(m=>openingFor(x,m.id)).length;
 const disabled=!b||x.paused||x.phase==='Closed';
 return `<div class="panel"><div class="eyebrow">02 / Independent openings</div><h2>One space for every voice.</h2><p>Copy each member’s initiation into their chat, then paste their opening remarks into their own card below. Each card saves separately. No member sees peer opinions until the debate begins.</p><div class="journey"><span>1. Briefing</span><strong>2. Openings · ${saved}/${x.members.length} saved</strong><span>3. Debate rounds</span><span>4. Final document & signatures</span></div>${!b?'<p class="warning">Freeze a briefing first.</p>':`<p class="tiny">Briefing v${b.version}. Saving a revision preserves the previous text. A started round keeps its original opening snapshot.</p>`}</div>
 ${x.members.map(m=>{const v=openingFor(x,m.id),id='opening-'+(b?.id||'draft')+'-'+m.id;return `<div class="panel opening-card"><div class="row"><h2>${esc(m.name)}</h2><span class="pill">${v?'Opening saved':'Awaiting opening'}</span></div><div class="persona-copy"><button data-opening-copy="${esc(m.id)}" ${disabled?'disabled':''}>Copy initiation for ${esc(m.name)}</button>${personaField(x,m)}</div><label for="${id}">${esc(m.name)} — opening remarks</label>${area(id,v?.text||'',`Paste only ${m.name}’s opening remarks here.`,true)}<div class="toolbar"><button class="primary" data-opening-save="${esc(m.id)}" data-field="${id}" ${disabled?'disabled':''}>Save ${esc(m.name)}’s opening</button></div>${v?`<p class="tiny">Saved ${esc(date(v.at))} · ${esc(v.id)}</p>`:''}</div>`;}).join('')}
 <div class="panel"><h2>Ready for the first debate?</h2><p>The first speaker receives all saved opening remarks labelled FROM: Council Member … and writes a message to the next member. Saving each reply prepares the next turn.</p><button id="startDebate" class="primary" ${disabled||saved!==x.members.length||currentRound(x)?'disabled':''}>Start round 1 · ${esc(orderedMembers(x)[0].name)} takes the floor</button>${currentRound(x)?'<button id="goDebate">Continue to Debate</button>':''}</div>${legacyDrafts(x)}`;
}
function legacyDrafts(x){
 const fields=['reply','context'].filter(id=>drafts[`${x.id}:${id}`]?.trim());
 const saved=x.responses.filter(v=>!v.stage);
 return fields.length||saved.length?`<details class="panel"><summary>Earlier work to place (${fields.length} drafts · ${saved.length} unassigned responses)</summary><p class="tiny">The earlier shared fields did not identify an opening’s author reliably. Your text is kept here; copy it into the correct member’s card. Responses linked to an opening handoff were matched automatically.</p>${fields.map(id=>`<h3>Earlier ${esc(id)} draft</h3><pre class="text">${esc(drafts[`${x.id}:${id}`])}</pre>`).join('')}${saved.map(v=>`<h3>${esc(v.author)} · ${esc(date(v.at))}</h3><pre class="text">${esc(v.text)}</pre>`).join('')}</details>`:'';
}
function debate(x){
 const r=currentRound(x),t=pendingTurn(r),h=t?x.handoffs.find(h=>h.id===t.handoffId):null;
 const disabled=x.paused||x.phase==='Closed';
 const savedTurns=(x.rounds||[]).flatMap(round=>round.turns.filter(turn=>turn.responseId).map(turn=>({round,turn})));
 const review=savedTurns.find(v=>v.turn.id===reviewTurnId);
 const summary=`<div class="panel"><div class="eyebrow">03 / The council relay</div><h2>${r?'Round '+r.number:'Opening remarks → debate → next round'}</h2><p>Each member can speak once per round; skip anyone who is unavailable. Copy the prepared prompt into the named member’s chat, paste their reply here, then save to pass the floor. You control when another round begins.</p>${r&&!roundComplete(r)?`<details><summary>Skip an unavailable reviewer</summary><div class="toolbar">${r.turns.filter(v=>!v.responseId&&!v.skippedAt).map(v=>`<button data-skip-reviewer="${v.id}" ${disabled?'disabled':''}>Skip ${esc(r.members.find(m=>m.id===v.memberId).name)}</button>`).join('')}</div></details>`:''}<div class="journey">${(r?.members||orderedMembers(x)).map(m=>{const turn=r?.turns.find(t=>t.memberId===m.id);return `<button data-review-turn="${turn?.id||''}" ${!turn||(!turn.responseId&&turn.id!==t?.id)?'disabled':''} class="${turn?.responseId?'done':turn?.skippedAt?'skipped':''} ${turn?.id===(review?.turn.id||t?.id)?'current':''}" aria-pressed="${turn?.id===(review?.turn.id||t?.id)}">${esc(m.name)}${r?.removedMemberIds?.includes(m.id)?' · removed':turn?.responseId?' ✓':turn?.skippedAt?' · skipped':''}</button>`;}).join(' → ')}</div>${x.speakingOrder?`<p class="tiny">Next round: ${orderedMembers(x).map(m=>esc(m.name)).join(' → ')}${t?'. This round keeps its original order.':'.'}</p>`:''}</div>`;
 let content='';
 if(review)content=reviewPanel(x,review,savedTurns);
 else if(!r)content=`<div class="panel"><h2>Collect openings first.</h2><p>Save every member’s independent opening in Openings, then start the first round. Changes to the briefing or roster require a fresh round with matching openings.</p><button id="goOpenings">Go to Openings</button></div>`;
 else if(t&&h){const speaker=r.members.find(m=>m.id===t.memberId),next=r.members.find(m=>m.id===t.toMemberId);content=`<div class="panel"><div class="toolbar">${savedTurns.length?`<button data-review-turn="${savedTurns.at(-1).turn.id}">← Previous turn</button>`:''}</div><div class="eyebrow">Round ${r.number} / Turn ${r.turns.indexOf(t)+1} of ${r.members.length}</div><h2>${esc(speaker.name)} → ${esc(next.name)}</h2><p class="tiny">Paste this prompt into <strong>${esc(speaker.name)}’s chat</strong>. Their response is addressed to ${esc(next.name)}${r.turns.indexOf(t)===r.members.length-1?', who can begin the next round when you choose.':', whose turn will be prepared next.'}</p><p class="tiny">Prompt size: ${h.text.length.toLocaleString()} characters${activeSummary(x)?' · reviewed summary + newer messages':' · full context'}. ${h.text.length>20000?'Long prompt: consider a summary checkpoint.':''}</p><button id="goSummarise">Summarise context</button><label for="debatePrompt">Prompt for ${esc(speaker.name)}</label><textarea id="debatePrompt" class="wide" readonly>${esc(h.text)}</textarea><div class="toolbar"><button id="copyDebate" class="primary" ${disabled?'disabled':''}>Copy prompt for ${esc(speaker.name)}</button>${personaField(x,speaker)}</div><p class="tiny">${h.copiedAt?'Copied '+esc(date(h.copiedAt)):'Ready to copy'} · Uses full context or your reviewed summary plus newer remarks and applicable interventions.</p><label for="turn-${t.id}">${esc(speaker.name)}’s reply · round ${r.number}</label>${area('turn-'+t.id,'',`Paste ${speaker.name}’s complete reply here.`,true)}<div class="toolbar"><button id="saveTurn" data-turn="${t.id}" class="primary" ${disabled?'disabled':''}>Save ${esc(speaker.name)}’s reply & ${r.turns.indexOf(t)===r.members.length-1?'finish round':'prepare '+esc(next.name)}</button><button id="skipReviewer" data-turn="${t.id}" ${disabled?'disabled':''}>Skip ${esc(speaker.name)}</button></div><p class="tiny">Saved turns remain in the round record below. Each turn has its own draft; moving between pages cannot assign it to another member.</p></div>`;}
 else content=`<div class="panel"><h2>Round ${r.number} complete.</h2><p>Every member has replied or been skipped. Skipping does not count as agreement. Continue the same relay for another round, or take a proposed document into final review. Agreement still requires individual signatures.</p><div class="toolbar"><button id="nextRound" class="primary" ${disabled?'disabled':''}>Start round ${r.number+1}</button><button id="goFinal">Move to final document</button></div></div>`;
 const history=(x.rounds||[]).slice().reverse().map(v=>`<details class="panel" ${v.id===r?.id?'open':''}><summary>Round ${v.number} · ${v.turns.filter(t=>t.responseId).length} replies · ${v.turns.filter(t=>t.skippedAt).length} skipped / ${v.members.length} turns${v.id!==r?.id?' · historical':''}</summary>${v.turns.map(turn=>{const reply=x.responses.find(p=>p.id===turn.responseId);return turn.skippedAt?`<div class="entry"><h3>${esc(v.members.find(m=>m.id===turn.memberId).name)} · skipped</h3><p class="tiny">Skipped by chair at ${esc(date(turn.skippedAt))}. No response or agreement implied.</p></div>`:reply?`<div class="entry"><h3>FROM: Council Member ${esc(reply.author)}</h3><p class="tiny">TO: Council Member ${esc(v.members.find(m=>m.id===turn.toMemberId).name)} · ${esc(date(reply.at))}</p><pre>${esc(reply.text)}</pre><button data-review-turn="${turn.id}">Review turn</button> <button data-proposal="${reply.id}">Use as final document draft</button></div>`:'';}).join('')}</details>`).join('');
 return summary+content+history+`<details class="panel"><summary>Other tools · implementer checks, signature handoffs, earlier records, claims</summary><p class="tiny">Optional manual tools. Opening remarks and debate rounds above keep their own separate records.</p>${advancedFloor(x)}</details>`;
}

function reviewPanel(x,selected,savedTurns){
 const {round,turn}=selected,reply=x.responses.find(v=>v.id===turn.responseId),h=x.handoffs.find(v=>v.id===reply.handoffId||v.id===turn.handoffId),index=savedTurns.findIndex(v=>v.turn.id===turn.id);
 const speaker=round.members.find(m=>m.id===turn.memberId),next=round.members.find(m=>m.id===turn.toMemberId);
 return `<div class="panel"><div class="eyebrow">Review / Round ${round.number} / Turn ${round.turns.indexOf(turn)+1} of ${round.members.length}</div><h2>${esc(speaker.name)} → ${esc(next.name)}</h2><p class="tiny">You are reviewing a saved turn. The current debate and its unfinished reply remain in place.</p><div class="toolbar"><button data-review-turn="${savedTurns[index-1]?.turn.id||''}" ${index===0?'disabled':''}>← Previous turn</button>${savedTurns[index+1]?`<button data-review-turn="${savedTurns[index+1].turn.id}">Next saved turn →</button>`:''}<button id="returnToCurrent" class="primary">Return to current turn</button></div><label for="reviewPrompt">Original prompt for ${esc(speaker.name)}</label><textarea id="reviewPrompt" class="wide" readonly>${esc(h?.text||'No prompt record available for this turn.')}</textarea><button id="copyReviewedPrompt" ${h?'':'disabled'}>Copy original prompt</button><label for="reviewReply">Saved reply from ${esc(speaker.name)}</label><textarea id="reviewReply" class="wide" readonly>${esc(reply.text)}</textarea><button id="copyReviewedReply">Copy saved reply</button><p class="tiny">Recorded ${esc(date(reply.at))}. Reviewing does not resend messages or change the speaking order.</p></div>`;
}
function summaryPage(x){const request=x.summaryRequests?.at(-1),summary=activeSummary(x);return `<div class="panel"><div class="eyebrow">Context checkpoint</div><h2>Keep the debate, reduce the baggage.</h2><p>Prepare the complete saved shared record for the current briefing, then give it to a model you choose with enough room for it. Bring back its summary and review it before continuing. The app does not select a model or send anything.</p><p class="tiny">Only recorded messages are included. Per-member interventions stay separate; originals and older summaries remain saved. New messages after the checkpoint are carried forward in full.</p><label for="summaryReviewer">Summariser / model</label>${input('summaryReviewer','Chosen large-context model','Name the model you want to use')}<label for="summaryBudget">Target words</label>${input('summaryBudget','1000')}<div class="toolbar"><button id="prepareSummary" class="primary" ${!x.briefings.length?'disabled':''}>Prepare full summary packet</button></div></div>${request?`<div class="panel"><h2>1. Give the packet to your summariser</h2><p class="tiny">${request.text.length.toLocaleString()} characters · ${request.responseIds.length} recorded responses · prepared ${esc(date(request.at))}. This packet is a fixed checkpoint; anything recorded later is not dropped.</p><label for="summaryPacket">Complete prompt and record</label><textarea id="summaryPacket" class="wide" readonly>${esc(request.text)}</textarea><div class="toolbar"><button id="copySummaryPacket">Copy full packet</button><button id="downloadSummaryPacket">Download packet as text</button></div><p class="tiny">If a chat input cuts off the packet, attach the downloaded file in a service that supports it. Check that it received the complete content; this dashboard cannot see provider input limits.</p></div><div class="panel"><h2>2. Review and use the summary</h2><label for="summaryText-${request.id}">Summariser’s response · editable for your review</label>${area('summaryText-'+request.id,'','Paste the full summary here, then review constraints, dissent, and evidence.',true)}<label><input id="summaryReviewed" type="checkbox" class="checkbox"> I reviewed the constraints, member attribution, evidence, and unresolved reservations.</label><button id="useSummary" class="primary">Use reviewed summary for future prompts</button></div>`:''}<div class="panel"><h2>Current context mode</h2><p>${summary?'Reviewed summary active · '+esc(summary.reviewer):'Full context — no active summary for this briefing.'}</p>${summary?`<pre class="text">${esc(summary.text)}</pre><button id="disableSummary">Restore full context</button>`:''}<button id="backToDebate">Return to debate</button><p class="tiny">Changing modes refreshes the pending prompt without advancing the round or clearing its draft. Copy the refreshed prompt again.</p>${(x.contextSummaries||[]).length?`<details><summary>Summary history (${x.contextSummaries.length})</summary>${x.contextSummaries.map(s=>`<div class="entry"><p class="tiny">${esc(s.reviewer)} · ${esc(date(s.at))} · ${esc(s.briefingId)}</p><pre>${esc(s.text)}</pre></div>`).join('')}</details>`:''}</div>`;}
function finalSummaryPanel(x){const d=latest(x),s=currentFinalSummary(x),request=x.finalSummaryRequests?.at(-1);return `<div class="panel"><div class="eyebrow">The outcome / Document v${d.version}</div><h2>Final document at a glance</h2><p class="tiny">A standalone outcome summary, separate from debate-context compression. The full document and signatures remain authoritative.</p>${s?`<pre class="text">${esc(s.text)}</pre><div class="toolbar"><button id="copyFinalOutcome">Copy outcome summary</button><button id="exportFinalOutcome">Export outcome summary</button></div>`:x.finalSummaries?.length?'<p class="warning">The previous summary is out of date. Prepare a new one for the current document, reservations, and approval.</p>':'<p class="tiny">No reviewed outcome summary saved yet.</p>'}<div class="toolbar"><button id="prepareFinalSummary" class="primary">Prepare final-document summary prompt</button></div>${request?`<details open><summary>Summarise this document and its reservations</summary><label for="finalSummaryPrompt">Complete summary request · final document only</label><textarea id="finalSummaryPrompt" class="wide" readonly>${esc(request.text)}</textarea><button id="copyFinalSummaryPrompt">Copy final-document summary prompt</button><label for="finalSummaryText-${request.id}">Outcome summary · paste and review</label>${area('finalSummaryText-'+request.id,'','Paste the summariser’s response. Keep the outcome, scope, actions, and last reservations clear.',true)}<label><input id="finalSummaryReviewed" type="checkbox" class="checkbox"> I checked the outcome, approval status, and each member’s reservations against the source.</label><button id="saveFinalSummary" class="primary">Save outcome summary</button></details>`:''}</div>`;}
function implementerNotesPanel(x){const d=latest(x);return `<div class="panel"><div class="eyebrow">Document v${d.version} / Implementer handoff</div><h2>Questions and comments from the council</h2><p class="tiny">Each member has their own saved notes for this document version. These accompany the final document and reservations. They do not alter its signed text.</p>${d.members.map(m=>{const note=implementerNote(x,m.id),id='implementer-note-'+d.id+'-'+m.id;return `<div class="entry"><h3>${esc(m.name)}</h3><button data-note-request="${m.id}">Copy questions request for ${esc(m.name)}</button><label for="${id}">${esc(m.name)}’s questions or comments for the implementer</label>${area(id,note?.text||'','Paste this member’s questions/comments, or “None”.')}<button data-save-note="${m.id}" data-field="${id}" class="primary">Save ${esc(m.name)}’s notes</button>${note?`<p class="tiny">Saved ${esc(date(note.at))}</p>`:''}</div>`;}).join('')}<div class="toolbar"><button id="copyImplementerHandoff" class="primary">Copy final document + council notes</button><button id="exportImplementerHandoff">Export implementer handoff</button></div><p class="tiny">Includes the document’s current approval status, every signature and reservation, and these member-specific notes.</p></div>`;}
function final(x){const d=latest(x);return `${d?finalSummaryPanel(x):''}<div class="panel"><div class="eyebrow">03 / The shared conclusion</div><h2>A document they can put their names to.</h2><p class="tiny">Circulate the same complete version to every member. Each signs with last reservations, or explicitly “None”. Blocking objections send it back for revision.</p><label for="document">Final document body</label>${area('document',d?.body||'','Problem · agreed approach · reasoning · scope · evidence · tests · unresolved assumptions · next actions',true)}<div class="toolbar"><button id="freezeDoc" class="primary">${d?'Freeze new version · request fresh signatures':'Freeze document for signatures'}</button></div></div>${d?implementerNotesPanel(x):''}${d?`<div class="panel"><div class="row"><h2>Signature register</h2><span class="pill">Document v${d.version}</span></div><p class="tiny">${esc(d.id)}<br>${agreed(x)?'All members agree to this version.':signoffComplete(x)?'Ready for your decision'+esc(approvalSkipLabel(x))+'.':'Agreement is incomplete.'}${d.rosterSuperseded?' Council membership changed: freeze a new document for the updated council.':d.briefingId!==x.briefings.at(-1)?.id?' Briefing changed: freeze a new document.':''}</p><p class="tiny">Copy the document to each chat, then paste that member’s full sign-off below. Reservations can stay in their reply. Each save is linked to document v${d.version} automatically.</p>${d.members.map(m=>{const s=x.signatures.filter(s=>s.memberId===m.id&&s.documentId===d.id).at(-1),id='signoff-'+d.id+'-'+m.id;return `<div class="sig ${s?.status==='Signed'?'signed':''}"><div class="row"><h3>${esc(m.name)}</h3><span class="tiny">${s?s.status==='Signed'?'Agreed':s.status==='Skipped'?'Approval skipped':'Changes requested':'Awaiting reply'}</span></div><button data-signoff-request="${m.id}">Copy sign-off request for ${esc(m.name)}</button><label for="${id}">${esc(m.name)}’s full reply</label>${area(id,s?.fullReply||s?.statement||'','Paste their agreement or requested changes, including any reservations.')}<div class="toolbar"><button data-simple-signoff="${m.id}" data-field="${id}" data-status="Signed" class="primary">Save agreement</button><button data-simple-signoff="${m.id}" data-field="${id}" data-status="Changes requested">Save changes requested</button><button data-skip-approval="${m.id}">Skip approval</button></div>${s?`<p class="tiny">Saved for document v${d.version} · ${esc(date(s.at))}</p>`:''}</div>`;}).join('')}</div><div class="panel"><h2>Your decision</h2><p class="tiny">Their agreement informs your decision. Only your explicit approval creates an implementation brief. Any departure from the shared document is your own direction.</p><label for="decision">Decision, reasons, accepted uncertainty, and approved scope</label>${area('decision',approved(x)?x.decisions.at(-1).body:'','Record what you authorise the implementer to do.')}<div class="toolbar"><button id="approve" class="primary" ${!signoffComplete(x)||x.paused?'disabled':''}>Approve implementation brief</button><button id="exportMd">Export ${approved(x)?'approved brief':'draft record'}</button></div></div>`:''}`;}
function record(x){return `<div class="panel"><div class="eyebrow">The record</div><h2>Every voice has a place.</h2><p class="tiny">Original responses, chair directions, and version history remain here. Backups preserve the complete structured record.</p><button id="exportMd">Export Markdown record</button>${[...x.responses.map(v=>({...v,type:v.author,body:v.text})),...x.interventions.map(v=>({...v,type:(v.source||'Chair')+' · '+v.type,body:(v.question?'Question: '+v.question+'\n\n':'')+v.text+'\nAudience: '+(v.target==='all'?'Whole council':x.members.find(m=>m.id===v.target)?.name||v.target)+'\nIncluded in '+x.handoffs.filter(h=>h.interventionIds.includes(v.id)).length+' prepared handoffs; '+x.handoffs.filter(h=>h.copiedAt&&h.interventionIds.includes(v.id)).length+' copied handoffs. Delivery unconfirmed.'})),...x.events.map(v=>({...v,type:'Chamber record',body:v.text}))].sort((a,b)=>b.at.localeCompare(a.at)).map(v=>`<div class="entry"><strong>${esc(v.type)}</strong><div class="tiny">${esc(date(v.at))} · ${esc(v.id)}</div><pre>${esc(v.body)}</pre></div>`).join('')||'<p class="empty">The chamber is ready. Start with a briefing.</p>'}<details><summary>Historical briefings and documents</summary>${x.briefings.map(b=>`<div class="entry"><h3>Briefing v${b.version}</h3><pre>${esc(b.body)}</pre></div>`).join('')}${x.documents.map(d=>`<div class="entry"><h3>Document v${d.version} · ${esc(d.id)}</h3><pre>${esc(d.body)}</pre>${x.signatures.filter(s=>s.documentId===d.id).map(s=>`<pre>${esc(d.members.find(m=>m.id===s.memberId)?.name)} · ${esc(s.status)} · ${esc(s.at)}\n${esc(s.statement)}\nReservations: ${esc(s.reservations)}</pre>`).join('')}</div>`).join('')}</details></div>`;}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function on(id,fn){if($(id))$(id).onclick=fn;}
function initiationPreview(memberId=c().members[0].id){
if(!$('initiationText'))return;
$('initiationRecipient').textContent='Preview for '+c().members.find(m=>m.id===memberId).name;
$('initiationText').value=c().briefings.length?prompt(c(),'Initiation',memberId).text:'Freeze a briefing above to prepare the member introduction.';
}
function bind(){initiationPreview();root.querySelectorAll('[data-persona]').forEach(field=>field.addEventListener('change',()=>{try{setPersona(c(),field.dataset.persona,field.value);field.value=c().personas?.[field.dataset.persona]||'';save();if($('initiationText'))initiationPreview(field.dataset.persona);const t=pendingTurn(currentRound(c()));if($('debatePrompt')&&t)$('debatePrompt').value=c().handoffs.find(h=>h.id===t.handoffId).text;notify('Persona saved. Future prompts for this member now include it.');}catch(e){notify(e.message,true);}}));root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{capture();tab=b.dataset.tab;render();});root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{capture();active=b.dataset.case;handoffId=null;reviewTurnId=null;render();});

root.querySelectorAll('[data-opening-copy]').forEach(button=>button.onclick=async()=>{try{
 const x=c(),h=prompt(x,'Initiation',button.dataset.openingCopy);await navigator.clipboard.writeText(h.text);h.copiedAt=now();x.handoffs.push(h);save();button.textContent='Copied for '+x.members.find(m=>m.id===h.memberId).name;notify('Paste into this member’s chat, then save their opening in this card.');
}catch(e){notify('Copy failed: '+e.message,true);}});
root.querySelectorAll('[data-opening-save]').forEach(button=>button.onclick=()=>action(()=>{saveOpening(c(),button.dataset.openingSave,$(button.dataset.field).value);draftClear(button.dataset.field);notify('Opening saved for this member.');}));
on('startDebate',()=>action(()=>{startRound(c());tab='Debate';reviewTurnId=null;}));
on('nextRound',()=>action(()=>{startRound(c());tab='Debate';reviewTurnId=null;}));
on('goDebate',()=>{capture();tab='Debate';render();});
on('goOpenings',()=>{capture();tab='Openings';render();});
on('goFinal',()=>{capture();tab='Final document';render();});
on('copyDebate',async()=>{try{const x=c(),r=currentRound(x),t=pendingTurn(r),h=x.handoffs.find(v=>v.id===t.handoffId);if(x.paused||x.phase==='Closed')throw Error('Resume or reopen the case first.');await navigator.clipboard.writeText(h.text);h.copiedAt=now();save();notify('Copied for '+r.members.find(m=>m.id===t.memberId).name+'.');}catch(e){notify('Copy failed: '+e.message,true);}});
on('saveTurn',()=>action(()=>{const id=$('saveTurn').dataset.turn;saveDebateReply(c(),id,$('turn-'+id).value);draftClear('turn-'+id);notify(roundComplete(currentRound(c()))?'Round complete. Choose another round or final review.':'Reply saved. The next member’s prompt is ready.');}));
root.querySelectorAll('[data-proposal]').forEach(button=>button.onclick=()=>{capture();const key=`${active}:document`,candidate=c().responses.find(r=>r.id===button.dataset.proposal).text;drafts[key]=drafts[key]?.trim()?drafts[key]+'\n\n--- Additional proposal for review ---\n\n'+candidate:candidate;tab='Final document';render();notify('Added to your final document draft for review. Existing draft text is retained; nothing is agreed or signed yet.');});

on('shuffleOrder',()=>action(()=>{shuffleOrder(c());notify(currentRound(c())&&!roundComplete(currentRound(c()))?'Order shuffled for the next round. This round and its drafts are unchanged.':'Speaking order shuffled.');}));

$('implementerPanel').addEventListener('toggle',()=>{c().implementerPanelOpen=$('implementerPanel').open;save();});
const refreshImplementerPreview=()=>{try{$('implementerRequestPreview').value=implementerRequest(c(),$('implementerQuestion').value,$('implementerRequester').value);}catch(e){$('implementerRequestPreview').value=e.message;}};
refreshImplementerPreview();$('implementerQuestion').addEventListener('input',refreshImplementerPreview);$('implementerRequester').addEventListener('change',refreshImplementerPreview);
on('copyImplementerRequest',async()=>{try{const x=c(),text=implementerRequest(x,$('implementerQuestion').value,$('implementerRequester').value);await navigator.clipboard.writeText(text);x.handoffs.push({id:uid(),memberId:'witness',kind:'Implementer check',briefingId:x.briefings.at(-1).id,documentId:null,text,interventionIds:[],at:now(),copiedAt:now()});save();notify('Request copied. Paste it into your implementer chat, then bring the reply back here.');}catch(e){notify('Copy failed: '+e.message,true);}});
on('injectImplementer',()=>action(()=>{injectImplementer(c(),{question:$('implementerQuestion').value,text:$('implementerReply').value,target:$('implementerTarget').value,requestedBy:$('implementerRequester').value});draftClear('implementerQuestion','implementerReply');c().implementerPanelOpen=true;notify('Implementer reply injected. The pending prompt is refreshed; copy it again before continuing.');}));


root.querySelectorAll('[data-review-turn]').forEach(button=>button.onclick=()=>{capture();const id=button.dataset.reviewTurn;reviewTurnId=pendingTurn(currentRound(c()))?.id===id?null:id;tab='Debate';render();});
on('returnToCurrent',()=>{capture();reviewTurnId=null;render();});
on('copyReviewedPrompt',async()=>{try{await navigator.clipboard.writeText($('reviewPrompt').value);notify('Original prompt copied.');}catch(e){notify('Copy failed: '+e.message,true);}});
on('copyReviewedReply',async()=>{try{await navigator.clipboard.writeText($('reviewReply').value);notify('Saved reply copied.');}catch(e){notify('Copy failed: '+e.message,true);}});


const skipTurn=turnId=>action(()=>{skipReviewer(c(),turnId);reviewTurnId=null;notify(roundComplete(currentRound(c()))?'Round complete. Skipped reviewers have not agreed.':'Reviewer skipped. The next prompt is ready; any unfinished draft is kept.');});
on('skipReviewer',()=>skipTurn($('skipReviewer').dataset.turn));
root.querySelectorAll('[data-skip-reviewer]').forEach(button=>button.onclick=()=>skipTurn(button.dataset.skipReviewer));


on('goSummarise',()=>{capture();tab='Summarise';render();});
on('backToDebate',()=>{capture();tab='Debate';render();});
on('prepareSummary',()=>action(()=>{prepareSummary(c(),$('summaryReviewer').value,Number($('summaryBudget').value));}));
on('copySummaryPacket',async()=>{try{await navigator.clipboard.writeText($('summaryPacket').value);notify('Full summary packet copied. Check it arrives without truncation.');}catch(e){notify('Copy failed: '+e.message+' Use the download button.',true);}});
on('downloadSummaryPacket',()=>download('council-summary-packet.txt',c().summaryRequests.at(-1).text,'text/plain'));
on('useSummary',()=>action(()=>{const request=c().summaryRequests.at(-1);useSummary(c(),request.id,$('summaryText-'+request.id).value,$('summaryReviewed').checked);draftClear('summaryText-'+request.id);notify('Reviewed summary activated. Newer messages remain in full; your current draft is kept.');}));
on('disableSummary',()=>action(()=>{disableSummary(c());notify('Full context restored.');}));


on('prepareFinalSummary',()=>action(()=>{prepareFinalSummary(c());}));
on('copyFinalSummaryPrompt',async()=>{try{await navigator.clipboard.writeText($('finalSummaryPrompt').value);notify('Final-document summary prompt copied.');}catch(e){notify(e.message,true);}});
on('saveFinalSummary',()=>action(()=>{const r=c().finalSummaryRequests.at(-1);saveFinalSummary(c(),r.id,$('finalSummaryText-'+r.id).value,$('finalSummaryReviewed').checked);draftClear('finalSummaryText-'+r.id);notify('Outcome summary saved above the final document.');}));
on('copyFinalOutcome',async()=>{try{await navigator.clipboard.writeText(exportFinalSummary(c()));notify('Outcome summary and last reservations copied.');}catch(e){notify(e.message,true);}});
on('exportFinalOutcome',()=>{try{download('council-outcome-summary.md',exportFinalSummary(c()),'text/markdown');}catch(e){notify(e.message,true);}});


root.querySelectorAll('[data-save-note]').forEach(button=>button.onclick=()=>action(()=>{saveImplementerNote(c(),button.dataset.saveNote,$(button.dataset.field).value);draftClear(button.dataset.field);notify('Member’s implementer notes saved separately.');}));
root.querySelectorAll('[data-note-request]').forEach(button=>button.onclick=async()=>{try{await navigator.clipboard.writeText(implementerNoteRequest(c(),button.dataset.noteRequest));notify('Request copied for this council member.');}catch(e){notify(e.message,true);}});
on('copyImplementerHandoff',async()=>{try{await navigator.clipboard.writeText(implementerHandoff(c()));notify('Final document, signatures, reservations, and saved member notes copied.');}catch(e){notify(e.message,true);}});
on('exportImplementerHandoff',()=>download('council-implementer-handoff.md',implementerHandoff(c()),'text/markdown'));

root.querySelectorAll('[data-skip-approval]').forEach(button=>button.onclick=()=>action(()=>{skipApproval(c(),button.dataset.skipApproval);notify('Approval skipped. This is recorded separately from member agreement.');}));

root.querySelectorAll('[data-remove-member]').forEach(button=>button.onclick=()=>action(()=>{const member=removeCouncilMember(c(),button.dataset.removeMember);draftClear('members');reviewTurnId=null;notify(member.name+' removed. Their earlier work and drafts are kept.');}));
root.querySelectorAll('[data-restore-member]').forEach(button=>button.onclick=()=>action(()=>{restoreCouncilMember(c(),button.dataset.restoreMember);draftClear('members');notify('Member restored. Skipped turns stay skipped this round.');}));

on('newCase',()=>action(()=>{const x=createCase('Untitled case');state.cases.push(x);active=x.id;tab='Briefing';handoffId=null;}));
on('backup',()=>{capture();download('council-backup.json',JSON.stringify({...state,workspaceDrafts:drafts},null,2),'application/json');});on('import',()=>$('file').click());$('file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>20_000_000)throw Error('Backup is too large (20 MB maximum).');const incoming=validateImport(JSON.parse(await file.text()));if(!confirm('Import cases? Existing cases with matching IDs will be kept; imported copies receive new case IDs.'))return;action(()=>{for(const raw of incoming.cases){const y=structuredClone(raw);y.id=uid();adoptLegacyOpenings(y);state.cases.push(y);for(const [key,value] of Object.entries(incoming.workspaceDrafts||{})){if(key.startsWith(raw.id+':')&&typeof value==='string')drafts[y.id+key.slice(raw.id.length)]=value;}}active=state.cases.at(-1).id;tab='Briefing';});notify('Cases imported alongside existing work.');}catch(e){notify('Import failed: '+e.message,true);}};
on('pause',()=>action(()=>{c().paused=!c().paused;event(c(),c().paused?'Chair paused the case.':'Chair resumed the case.');}));on('close',()=>action(()=>{c().phase=c().phase==='Closed'?'Debate':'Closed';event(c(),c().phase==='Closed'?'Chair closed the case. Agreement and approval statuses are preserved separately.':'Chair reopened the case.');}));
on('interject',()=>action(()=>{if(!$('comment').value.trim())throw Error('Write your comment first.');c().interventions.push({id:uid(),type:$('interventionType').value,target:$('target').value,text:$('comment').value,at:now()});refreshDebatePrompt(c());draftClear('comment');notify('Recorded. Include it in the next relevant handoff.');}));
on('freezeBrief',()=>action(()=>{const title=$('title').value.trim();if(!title)throw Error('Give this case a name.');reviseBriefing(c(),$('briefing').value);c().title=title;draftClear('briefing','title');tab='Openings';}));
root.querySelectorAll('[data-initiation]').forEach(button=>button.onclick=async()=>{try{
const x=c(),memberId=button.dataset.initiation,b=x.briefings.at(-1);
initiationPreview(memberId);
if(x.paused||x.phase==='Closed')throw Error('Resume or reopen the case before copying an initiation.');
if(!b)throw Error('Freeze a briefing first.');
if($('briefing').value!==b.body||$('title').value.trim()!==x.title)throw Error('Freeze your briefing edits before copying so every member receives the same version.');
const h=prompt(x,'Initiation',memberId);await navigator.clipboard.writeText(h.text);
h.copiedAt=now();x.handoffs.push(h);handoffId=h.id;draftClear('promptText');save();
button.textContent='Copied for '+x.members.find(m=>m.id===memberId).name;
notify('Initiation copied for '+x.members.find(m=>m.id===memberId).name+'. Paste it into their chat; save their reply in their own card under Openings.');
}catch(e){notify(e.message+' The initiation text is available below for manual copying.',true);}});
on('saveMembers',()=>action(()=>{const names=$('members').value.split('\n').map(t=>t.trim()).filter(Boolean);if(!names.length||new Set(names).size!==names.length)throw Error('Use at least one member and unique names.');if(names.join('\n')===c().members.map(m=>m.name).join('\n'))return;if(names.every(name=>c().members.some(m=>m.name===name))){for(const m of c().members.slice())if(!names.includes(m.name))removeCouncilMember(c(),m.id);}c().members=names.map(name=>c().members.find(m=>m.name===name)||{id:uid(),name});delete c().speakingOrder;event(c(),'Chair updated the council: '+names.join(' → '));if(latest(c())){c().phase='Final document';latest(c()).rosterSuperseded=true;}draftClear('members');}));
on('prepare',()=>action(()=>{const h=prompt(c(),$('kind').value,$('speaker').value,$('context').value);c().handoffs.push(h);handoffId=h.id;draftClear('promptText');if(h.kind==='Rebuttal')c().phase='Debate';}));
if($('handoffSelect'))$('handoffSelect').onchange=()=>{capture();handoffId=$('handoffSelect').value;draftClear('promptText');render();};
on('copy',async()=>{try{const h=c().handoffs.find(h=>h.id===handoffId&&h.kind!=='Debate')||c().handoffs.filter(h=>h.kind!=='Debate').at(-1);if(h.copiedAt&&$('promptText').value!==h.text)throw Error('This prompt was already copied. Prepare a new handoff to revise it.');h.text=$('promptText').value;await navigator.clipboard.writeText(h.text);h.copiedAt=now();$('promptText').readOnly=true;save();notify('Copied. Paste it into the chosen chat; delivery is not confirmed.');}catch(e){notify('Could not copy: '+e.message+' You can select the prompt and copy manually.',true);}});
on('response',()=>action(()=>{const h=c().handoffs.find(h=>h.id===handoffId&&h.kind!=='Debate')||c().handoffs.filter(h=>h.kind!=='Debate').at(-1);const reply=$('reply-'+h.id);if(!reply.value.trim())throw Error('Paste a response first.');c().responses.push({id:uid(),handoffId:h.id,briefingId:h.briefingId,author:h.memberId==='witness'?'Implementer':c().members.find(m=>m.id===h.memberId)?.name||'Former member',text:reply.value,at:now()});draftClear('reply-'+h.id);notify('Response recorded.');}));
on('addClaim',()=>action(()=>{if(!$('claim').value.trim())throw Error('Add a claim first.');c().claims.push({id:uid(),text:$('claim').value,status:$('claimStatus').value,at:now()});draftClear('claim');}));root.querySelectorAll('[data-claim]').forEach(el=>el.onchange=()=>action(()=>{const q=c().claims.find(q=>q.id===el.dataset.claim);event(c(),`Claim ${q.id}: ${q.status} → ${el.value}`);q.status=el.value;}));
on('freezeDoc',()=>action(()=>{freezeDocument(c(),$('document').value);draftClear('document','statement','reservations','decision');}));
root.querySelectorAll('[data-simple-signoff]').forEach(button=>button.onclick=()=>action(()=>{saveSimpleSignoff(c(),button.dataset.simpleSignoff,$(button.dataset.field).value,button.dataset.status);draftClear(button.dataset.field);notify('Member reply saved for this document version.');}));
root.querySelectorAll('[data-signoff-request]').forEach(button=>button.onclick=async()=>{try{const x=c(),d=latest(x),m=d.members.find(m=>m.id===button.dataset.signoffRequest);const text=`You are Council Member ${m.name}. Review final document v${d.version} (${d.id}) below. Reply AGREED or CHANGES REQUESTED, then give your last reservations (or explicitly “None”). Sign with your council member name. If you require amendments before accepting, say CHANGES REQUESTED. Do not sign for others. This is council review; implementation still requires the human chair’s separate approval.\n\n${d.body}`;await navigator.clipboard.writeText(text);notify('Sign-off request copied for '+m.name+'.');}catch(e){notify(e.message,true);}});
on('approve',()=>action(()=>{if(latest(c())?.rosterSuperseded)throw Error('Freeze a new document and collect fresh signatures.');approve(c(),$('decision').value);draftClear('decision');notify('Your implementation brief is approved. Nothing has been sent or executed.');}));on('exportMd',()=>download('council-record.md',markdown(c()),'text/markdown'));
root.querySelectorAll('[data-draft]').forEach(el=>el.addEventListener('input',()=>{capture();try{localStorage.setItem(KEY+'.drafts',JSON.stringify(drafts));}catch{notify('Draft could not be saved. Copy your text or export a backup.',true);}}));}
try{drafts=JSON.parse(localStorage.getItem(KEY+'.drafts')||sessionStorage.getItem(KEY+'.drafts')||'{}');}catch{}
try{const view=JSON.parse(localStorage.getItem(KEY+'.view')||'null');if(view&&state.cases.some(x=>x.id===view.active)){active=view.active;reviewTurnId=view.reviewTurnId||null;if(['Briefing','Openings','Debate','Summarise','Final document','Record'].includes(view.tab))tab=view.tab;}}catch{}
render();if(!saveError)save();
